  1→import { Head, router } from '@inertiajs/react';
  2→import { Baby, Check, CheckCircle, ChevronLeft, ChevronRight, Camera, Pencil, AlertTriangle } from 'lucide-react';
  3→import { useEffect, useState } from 'react';
  4→import AppLayout from '@/layouts/app-layout';
  5→import type { BreadcrumbItem } from '@/types';
  6→
  7→interface Animal {
  8→    id: number;
  9→    crotal_code: string;
 10→    breed: string;
 11→    sex: string;
 12→    name: string | null;
 13→    birth_date: string;
 14→}
 15→
 16→interface SubExploitation {
 17→    id: number;
 18→    species: string;
 19→    exploitation_type: string;
 20→    current_capacity: number;
 21→    max_capacity: number;
 22→    status: string;
 23→    animals: Animal[];
 24→}
 25→
 26→interface Exploitation {
 27→    id: number;
 28→    name: string;
 29→    rega_code: string;
 30→    sub_exploitations: SubExploitation[];
 31→}
 32→
 33→interface SuccessData {
 34→    message: string;
 35→    reference_code: string;
 36→    calves: Array<{ name: string | null; sex: string; crotal: string }>;
 37→    new_capacity: number;
 38→}
 39→
 40→interface Props {
 41→    exploitation: Exploitation | null;
 42→    success?: SuccessData | null;
 43→}
 44→
 45→interface CalfData {
 46→    sex: string;
 47→    breed: string;
 48→    name: string;
 49→    birth_date: string;
 50→}
 51→
 52→const breadcrumbs: BreadcrumbItem[] = [
 53→    { title: 'Mi Explotación', href: '/dashboard' },
 54→    { title: 'Comunicar Nacimiento', href: '/nacimientos/crear' },
 55→];
 56→
 57→const STEPS = [
 58→    'Subexplotación',
 59→    'Madre',
 60→    'Padre',
 61→    'Datos cría',
 62→    'Resumen',
 63→    'Confirmación',
 64→];
 65→
 66→const speciesLabels: Record<string, string> = {
 67→    bovine: 'Bovino',
 68→    ovine: 'Ovino',
 69→    caprine: 'Caprino',
 70→    equine: 'Equino',
 71→};
 72→
 73→function ProgressBar({ currentStep }: { currentStep: number }) {
 74→    return (
 75→        <div className="flex gap-1">
 76→            {STEPS.map((_, i) => (
 77→                <div key={i} className={`h-1 flex-1 ${i <= currentStep ? 'bg-[#E53935]' : 'bg-[#E0E0E0]'}`} />
 78→            ))}
 79→        </div>
 80→    );
 81→}
 82→
 83→function Step1({ subExploitations, onSelect }: { subExploitations: SubExploitation[]; onSelect: (s: SubExploitation) => void }) {
 84→    return (
 85→        <div className="flex flex-col gap-4">
 86→            <h2 className="text-2xl font-bold">Seleccionar subexplotación</h2>
 87→            <p className="text-sm leading-[1.4] text-[#757575]">Elige la subexplotación donde se registrará el nacimiento.</p>
 88→            {subExploitations.filter(s => ['bovine', 'ovine', 'caprine', 'equine'].includes(s.species)).map((sub) => {
 89→                const isFull = sub.current_capacity >= sub.max_capacity;
 90→                return (
 91→                    <button
 92→                        key={sub.id}
 93→                        onClick={() => !isFull && onSelect(sub)}
 94→                        disabled={isFull}
 95→                        className={`flex flex-col gap-2 border-2 border-black p-4 text-left ${isFull ? 'opacity-50' : 'hover:bg-[#F5F5F5]'}`}
 96→                    >
 97→                        <div className="flex items-center justify-between">
 98→                            <span className="text-sm font-bold">{speciesLabels[sub.species] || sub.species} · {sub.exploitation_type}</span>
 99→                            <span className={`px-2 py-0.5 text-xs font-bold ${isFull ? 'bg-[#FFEBEE] text-[#E53935]' : 'bg-[#E8F5E9] text-[#2E7D32]'}`}>
100→                                {sub.current_capacity}/{sub.max_capacity}
101→                            </span>
102→                        </div>
103→                        <div className="h-1.5 w-full bg-[#F5F5F5]">
104→                            <div className={`h-1.5 ${isFull ? 'bg-[#E53935]' : 'bg-[#2E7D32]'}`} style={{ width: `${(sub.current_capacity / sub.max_capacity) * 100}%` }} />
105→                        </div>
106→                        {isFull && <p className="text-xs text-[#E53935]">Capacidad máxima alcanzada</p>}
107→                    </button>
108→                );
109→            })}
110→        </div>
111→    );
112→}
113→
114→function Step2({ animals, selectedId, onSelect }: { animals: Animal[]; selectedId: number | null; onSelect: (id: number) => void }) {
115→    const females = animals.filter((a) => a.sex === 'female' && a.birth_date);
116→    const [search, setSearch] = useState('');
117→    const filtered = females.filter((a) => a.crotal_code.includes(search) || (a.name && a.name.toLowerCase().includes(search.toLowerCase())));
118→
119→    return (
120→        <div className="flex flex-col gap-4">
121→            <h2 className="text-2xl font-bold">Seleccionar madre</h2>
122→            <p className="text-sm leading-[1.4] text-[#757575]">Selecciona la hembra que es madre del animal nacido.</p>
123→            <div className="flex gap-2">
124→                <input
125→                    type="text"
126→                    value={search}
127→                    onChange={(e) => setSearch(e.target.value)}
128→                    placeholder="Buscar por crotal o nombre..."
129→                    className="h-[52px] flex-1 bg-[#F5F5F5] px-[18px] text-sm"
130→                />
131→                <button
132→                    onClick={() => router.visit('/scanner?returnTo=/nacimientos/crear')}
133→                    className="flex size-[52px] shrink-0 items-center justify-center border-2 border-black"
134→                    title="Escanear crotal"
135→                >
136→                    <Camera className="size-5" />
137→                </button>
138→            </div>
139→            <div className="flex flex-col gap-2">
140→                {filtered.map((a) => {
141→                    const age = Math.floor((Date.now() - new Date(a.birth_date).getTime()) / (365.25 * 24 * 60 * 60 * 1000));
142→                    return (
143→                        <button
144→                            key={a.id}
145→                            onClick={() => onSelect(a.id)}
146→                            className={`flex items-center gap-3 border-2 p-3 text-left ${selectedId === a.id ? 'border-[#E53935] bg-[#FFF5F5]' : 'border-black'}`}
147→                        >
148→                            {selectedId === a.id && <Check className="size-5 shrink-0 text-[#E53935]" />}
149→                            <div className="flex-1">
150→                                <p className="text-sm font-bold">{a.crotal_code}</p>
151→                                <p className="text-xs text-[#757575]">{a.breed} · {age} años{a.name ? ` · ${a.name}` : ''}</p>
152→                            </div>
153→                        </button>
154→                    );
155→                })}
156→            </div>
157→        </div>
158→    );
159→}
160→
161→function Step3({ animals, selectedId, onSelect, onSkip }: { animals: Animal[]; selectedId: number | null; onSelect: (id: number) => void; onSkip: () => void }) {
162→    const males = animals.filter((a) => a.sex === 'male');
163→
164→    return (
165→        <div className="flex flex-col gap-4">
166→            <h2 className="text-2xl font-bold">Padre (opcional)</h2>
167→            <p className="text-sm leading-[1.4] text-[#757575]">Si conoces al padre, selecciónalo. Puedes omitir este paso.</p>
168→            <button onClick={onSkip} className="w-full border-2 border-black py-3 text-center text-sm font-semibold">
169→                Omitir este paso
170→            </button>
171→            {males.map((a) => (
172→                <button
173→                    key={a.id}
174→                    onClick={() => onSelect(a.id)}
175→                    className={`flex items-center gap-3 border-2 p-3 text-left ${selectedId === a.id ? 'border-[#E53935] bg-[#FFF5F5]' : 'border-black'}`}
176→                >
177→                    {selectedId === a.id && <Check className="size-5 shrink-0 text-[#E53935]" />}
178→                    <div>
179→                        <p className="text-sm font-bold">{a.crotal_code}</p>
180→                        <p className="text-xs text-[#757575]">{a.breed}{a.name ? ` · ${a.name}` : ''}</p>
181→                    </div>
182→                </button>
183→            ))}
184→        </div>
185→    );
186→}
187→
188→function Step4({ motherBreed, calves, onUpdate }: { motherBreed: string; calves: CalfData[]; onUpdate: (calves: CalfData[]) => void }) {
189→    const today = new Date().toISOString().split('T')[0];
190→    const updateCalf = (index: number, field: keyof CalfData, value: string) => {
191→        const updated = [...calves];
192→        updated[index] = { ...updated[index], [field]: value };
193→        onUpdate(updated);
194→    };
195→    const addCalf = () => {
196→        onUpdate([...calves, { sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
197→    };
198→    const removeCalf = (index: number) => {
199→        if (calves.length > 1) onUpdate(calves.filter((_, i) => i !== index));
200→    };
201→
202→    return (
203→        <div className="flex flex-col gap-4">
204→            <h2 className="text-2xl font-bold">Datos de la cría</h2>
205→            {calves.map((calf, i) => {
206→                const daysAgo = Math.floor((Date.now() - new Date(calf.birth_date).getTime()) / (1000 * 60 * 60 * 24));
207→                return (
208→                    <div key={i} className="flex flex-col gap-3 border-2 border-black p-4">
209→                        <div className="flex items-center justify-between">
210→                            <span className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Cría {calves.length > 1 ? i + 1 : ''}</span>
211→                            {calves.length > 1 && (
212→                                <button onClick={() => removeCalf(i)} className="text-xs text-[#E53935]">Eliminar</button>
213→                            )}
214→                        </div>
215→                        <div>
216→                            <label className="text-xs font-semibold text-[#757575]">Fecha de nacimiento</label>
217→                            <input type="date" value={calf.birth_date} onChange={(e) => updateCalf(i, 'birth_date', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-sm" />
218→                            {daysAgo > 7 && <p className="mt-1 text-xs font-medium text-[#E65100]">Supera el plazo legal de 7 días. Se recomienda registrarlo cuanto antes.</p>}
219→                        </div>
220→                        <div>
221→                            <label className="text-xs font-semibold text-[#757575]">Sexo</label>
222→                            <div className="mt-1 flex gap-0">
223→                                {(['female', 'male'] as const).map((s) => (
224→                                    <button key={s} onClick={() => updateCalf(i, 'sex', s)} className={`flex-1 border-2 border-black py-2 text-xs font-bold ${calf.sex === s ? 'bg-black text-white' : ''}`}>
225→                                        {s === 'female' ? 'Hembra' : 'Macho'}
226→                                    </button>
227→                                ))}
228→                            </div>
229→                        </div>
230→                        <div>
231→                            <label className="text-xs font-semibold text-[#757575]">Raza</label>
232→                            <input type="text" value={calf.breed} onChange={(e) => updateCalf(i, 'breed', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-sm" />
233→                        </div>
234→                        <div>
235→                            <label className="text-xs font-semibold text-[#757575]">Nombre (opcional)</label>
236→                            <input type="text" value={calf.name} onChange={(e) => updateCalf(i, 'name', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-sm" placeholder="Ej: Txuri" />
237→                        </div>
238→                    </div>
239→                );
240→            })}
241→            <button onClick={addCalf} className="w-full border-2 border-black py-3 text-center text-sm font-semibold">
242→                + Añadir otra cría
243→            </button>
244→        </div>
245→    );
246→}
247→
248→function Step5({ sub, mother, father, calves, animals, onEditStep }: { sub: SubExploitation; mother: number; father: number | null; calves: CalfData[]; animals: Animal[]; onEditStep: (step: number) => void }) {
249→    const motherAnimal = animals.find((a) => a.id === mother);
250→    const fatherAnimal = father ? animals.find((a) => a.id === father) : null;
251→    const oldestCalfDaysAgo = Math.max(...calves.map((c) => Math.floor((Date.now() - new Date(c.birth_date).getTime()) / (1000 * 60 * 60 * 24))));
252→    const withinLegalDeadline = oldestCalfDaysAgo <= 7;
253→
254→    return (
255→        <div className="flex flex-col gap-4">
256→            <h2 className="text-2xl font-bold">Resumen</h2>
257→            <div className="flex flex-col gap-3 border-2 border-black p-4">
258→                <div className="flex items-start justify-between">
259→                    <div>
260→                        <p className="text-xs text-[#757575]">Subexplotación</p>
261→                        <p className="text-sm font-bold">{speciesLabels[sub.species]} · {sub.exploitation_type}</p>
262→                    </div>
263→                    <button onClick={() => onEditStep(0)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
264→                        <Pencil className="size-3" /> Editar
265→                    </button>
266→                </div>
267→                <div className="flex items-start justify-between">
268→                    <div>
269→                        <p className="text-xs text-[#757575]">Madre</p>
270→                        <p className="text-sm font-bold">{motherAnimal?.crotal_code} {motherAnimal?.name ? `(${motherAnimal.name})` : ''}</p>
271→                    </div>
272→                    <button onClick={() => onEditStep(1)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
273→                        <Pencil className="size-3" /> Editar
274→                    </button>
275→                </div>
276→                <div className="flex items-start justify-between">
277→                    <div>
278→                        <p className="text-xs text-[#757575]">Padre</p>
279→                        <p className="text-sm font-bold">{fatherAnimal ? `${fatherAnimal.crotal_code} ${fatherAnimal.name ? `(${fatherAnimal.name})` : ''}` : 'No indicado'}</p>
280→                    </div>
281→                    <button onClick={() => onEditStep(2)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
282→                        <Pencil className="size-3" /> Editar
283→                    </button>
284→                </div>
285→                <div className="mt-2 border-t-2 border-black pt-3">
286→                    <div className="flex items-start justify-between">
287→                        <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Crías ({calves.length})</p>
288→                        <button onClick={() => onEditStep(3)} className="flex items-center gap-1 text-xs font-semibold text-[#E53935]">
289→                            <Pencil className="size-3" /> Editar
290→                        </button>
291→                    </div>
292→                    {calves.map((c, i) => (
293→                        <div key={i} className="mt-2 flex items-center justify-between text-sm">
294→                            <span>{c.sex === 'female' ? 'Hembra' : 'Macho'} · {c.breed}</span>
295→                            <span className="text-[#757575]">{new Date(c.birth_date).toLocaleDateString('es-ES')}</span>
296→                        </div>
297→                    ))}
298→                </div>
299→            </div>
300→
301→            <div className="flex flex-col gap-2 border-2 border-black p-4">
302→                <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Validación</p>
303→                <div className="flex items-center gap-2">
304→                    <CheckCircle className="size-4 text-[#2E7D32]" />
305→                    <span className="text-xs text-[#2E7D32]">Madre activa en la explotación</span>
306→                </div>
307→                <div className="flex items-center gap-2">
308→                    <CheckCircle className="size-4 text-[#2E7D32]" />
309→                    <span className="text-xs text-[#2E7D32]">Capacidad disponible ({sub.current_capacity + calves.length}/{sub.max_capacity})</span>
310→                </div>
311→                <div className="flex items-center gap-2">
312→                    {withinLegalDeadline ? (
313→                        <>
314→                            <CheckCircle className="size-4 text-[#2E7D32]" />
315→                            <span className="text-xs text-[#2E7D32]">Dentro del plazo legal (7 días)</span>
316→                        </>
317→                    ) : (
318→                        <>
319→                            <AlertTriangle className="size-4 text-[#E65100]" />
320→                            <span className="text-xs text-[#E65100]">Fuera del plazo legal de 7 días</span>
321→                        </>
322→                    )}
323→                </div>
324→            </div>
325→        </div>
326→    );
327→}
328→
329→function Step6({ referenceCode, calves, newCapacity, maxCapacity }: { referenceCode: string; calves: Array<{ name: string | null; sex: string; crotal: string }>; newCapacity: number; maxCapacity: number }) {
330→    const [showCheck, setShowCheck] = useState(false);
331→
332→    useEffect(() => {
333→        const timer = setTimeout(() => setShowCheck(true), 100);
334→        return () => clearTimeout(timer);
335→    }, []);
336→
337→    return (
338→        <div className="flex flex-col items-center gap-5 py-8 text-center">
339→            <div
340→                className="flex size-16 items-center justify-center bg-[#E8F5E9] transition-all duration-500"
341→                style={{ transform: showCheck ? 'scale(1)' : 'scale(0)', opacity: showCheck ? 1 : 0 }}
342→            >
343→                <CheckCircle className="size-8 text-[#2E7D32]" />
344→            </div>
345→            <h2 className="text-2xl font-bold">¡Nacimiento registrado!</h2>
346→            <p className="text-sm text-[#757575]">Referencia: <span className="font-bold text-black">{referenceCode}</span></p>
347→            {calves.length > 0 && (
348→                <div className="w-full border-2 border-black p-4">
349→                    <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Crotales asignados</p>
350→                    {calves.map((c, i) => (
351→                        <div key={i} className="mt-2 flex items-center justify-between">
352→                            <span className="text-sm font-bold">{c.crotal}</span>
353→                            <span className="text-xs text-[#757575]">{c.sex === 'female' ? 'Hembra' : 'Macho'}{c.name ? ` · ${c.name}` : ''}</span>
354→                        </div>
355→                    ))}
356→                </div>
357→            )}
358→            {newCapacity > 0 && maxCapacity > 0 && (
359→                <div className="w-full border-2 border-black p-4">
360→                    <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Capacidad actualizada</p>
361→                    <div className="mt-2 flex items-center justify-between">
362→                        <span className="text-sm font-bold">{newCapacity}/{maxCapacity}</span>
363→                        <span className={`px-2 py-0.5 text-xs font-bold ${newCapacity >= maxCapacity ? 'bg-[#FFEBEE] text-[#E53935]' : 'bg-[#E8F5E9] text-[#2E7D32]'}`}>
364→                            {maxCapacity - newCapacity} plazas libres
365→                        </span>
366→                    </div>
