384→export default function CrearNacimiento({ exploitation, success }: Props) {
385→    const [step, setStep] = useState(() => {
386→        if (success?.reference_code) return 5;
387→        return 0;
388→    });
389→    const [subExploitation, setSubExploitation] = useState<SubExploitation | null>(null);
390→    const [motherId, setMotherId] = useState<number | null>(null);
391→    const [fatherId, setFatherId] = useState<number | null>(null);
392→    const [calves, setCalves] = useState<CalfData[]>([]);
393→    const [submitting, setSubmitting] = useState(false);
394→    const [result, setResult] = useState<{ reference_code: string; calves: Array<{ name: string | null; sex: string; crotal: string }>; new_capacity: number; max_capacity: number } | null>(() => {
395→        if (success?.reference_code) {
396→            return {
397→                reference_code: success.reference_code,
398→                calves: success.calves || [],
399→                new_capacity: success.new_capacity || 0,
400→                max_capacity: 0,
401→            };
402→        }
403→        return null;
404→    });
405→
406→    const today = new Date().toISOString().split('T')[0];
407→
408→    const handleSubSelect = (sub: SubExploitation) => {
409→        setSubExploitation(sub);
410→        const motherBreed = sub.animals.find((a) => a.sex === 'female')?.breed || '';
411→        setCalves([{ sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
412→        setStep(1);
413→    };
414→
415→    const handleMotherSelect = (id: number) => {
416→        setMotherId(id);
417→        const mother = subExploitation?.animals.find((a) => a.id === id);
418→        if (mother) {
419→            setCalves((prev) => prev.map((c) => ({ ...c, breed: mother.breed })));
420→        }
421→    };
422→
423→    const handleSubmit = () => {
424→        if (!subExploitation || !motherId) return;
425→        setSubmitting(true);
426→
427→        router.post('/nacimientos', {
428→            sub_exploitation_id: subExploitation.id,
429→            mother_id: motherId,
430→            father_id: fatherId,
431→            birth_type: calves.length > 1 ? 'multiple' : 'simple',
432→            calf_count: calves.length,
433→            calves: calves.map((c) => ({
434→                sex: c.sex,
435→                breed: c.breed,
436→                name: c.name || null,
437→                birth_date: c.birth_date,
438→            })),
439→        }, {
440→            onSuccess: (page) => {
441→                const successData = (page.props as any).success;
442→                if (successData) {
443→                    setResult({
444→                        reference_code: successData.reference_code,
445→                        calves: successData.calves || [],
446→                        new_capacity: successData.new_capacity || 0,
447→                        max_capacity: subExploitation.max_capacity,
448→                    });
449→                    setStep(5);
450→                }
451→            },
452→            onError: () => setSubmitting(false),
453→        });
454→    };
455→
456→    const canNext = () => {
457→        if (step === 0) return !!subExploitation;
458→        if (step === 1) return !!motherId;
459→        if (step === 3) return calves.every((c) => c.birth_date && c.sex && c.breed);
460→        return true;
461→    };
462→
463→    return (
464→        <AppLayout breadcrumbs={breadcrumbs}>
465→            <Head title="Comunicar Nacimiento" />
466→            <div className="flex flex-col gap-5 p-6">
467→                {step < 5 && (
468→                    <>
469→                        <ProgressBar currentStep={step} />
470→                        <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Paso {step + 1} de 6</p>
471→                    </>
472→                )}
473→
474→                {step === 0 && !exploitation && (
475→                    <div className="flex flex-col items-center gap-4 py-12 text-center">
476→                        <Baby className="size-12 text-[#BDBDBD]" />
477→                        <h2 className="text-2xl font-bold">Sin explotación asignada</h2>
478→                        <p className="text-sm leading-[1.4] text-[#757575]">No tienes ninguna explotación asociada a tu cuenta. Contacta con tu administrador para que te asigne una.</p>
479→                        <button onClick={() => router.visit('/dashboard')} className="mt-2 border-2 border-black px-6 py-3 text-sm font-semibold">
480→                            Volver al panel
481→                        </button>
482→                    </div>
483→                )}
484→                {step === 0 && exploitation && <Step1 subExploitations={exploitation.sub_exploitations} onSelect={handleSubSelect} />}
485→                {step === 1 && subExploitation && <Step2 animals={subExploitation.animals} selectedId={motherId} onSelect={handleMotherSelect} />}
486→                {step === 2 && subExploitation && <Step3 animals={subExploitation.animals} selectedId={fatherId} onSelect={setFatherId} onSkip={() => { setFatherId(null); setStep(3); }} />}
487→                {step === 3 && subExploitation && (
488→                    <Step4
489→                        motherBreed={subExploitation.animals.find((a) => a.id === motherId)?.breed || ''}
490→                        calves={calves}
491→                        onUpdate={setCalves}
492→                    />
493→                )}
494→                {step === 4 && subExploitation && (
495→                    <Step5 sub={subExploitation} mother={motherId!} father={fatherId} calves={calves} animals={subExploitation.animals} onEditStep={setStep} />
496→                )}
497→                {step === 5 && result && <Step6 referenceCode={result.reference_code} calves={result.calves} newCapacity={result.new_capacity} maxCapacity={result.max_capacity} />}
498→
499→                {step > 0 && step < 5 && (
500→                    <div className="flex gap-2">
501→                        <button onClick={() => setStep(step - 1)} className="flex items-center gap-1 border-2 border-black px-4 py-3 text-sm font-semibold">
502→                            <ChevronLeft className="size-4" /> Atrás
503→                        </button>
504→                        <div className="flex-1" />
505→                        {step < 4 ? (
506→                            <button
507→                                onClick={() => setStep(step + 1)}
508→                                disabled={!canNext()}
509→                                className="flex items-center gap-1 bg-[#E53935] px-6 py-3 text-sm font-bold text-white disabled:opacity-50"
510→                            >
511→                                Siguiente <ChevronRight className="size-4" />
512→                            </button>
